import { CONNECTION_STRING } from '@/lib/config'
import { getOrCreateDocAndToken } from '@y-sweet/sdk'
import { NextResponse } from 'next/server'

const CORS_HEADERS = {
  'access-control-allow-origin': '*',
  'access-control-allow-methods': 'POST',
  'access-control-allow-headers': 'content-type',
}

export async function OPTIONS(request: Request) {
  return new Response(null, { status: 204, headers: CORS_HEADERS })
}

export async function POST(request: Request) {
  // In a production app, you'd want to validate that the user is authenticated
  // and has access to the given doc.

  const { docId } = await request.json()
  const clientToken = await getOrCreateDocAndToken(CONNECTION_STRING, docId)
  return NextResponse.json(clientToken, { headers: CORS_HEADERS })
}

import { expect, test } from 'vitest'
import { YSweetError, YSweetErrorPayload } from '@y-sweet/sdk'

function expectRoundTrip(payload: YSweetErrorPayload) {
  const message = YSweetError.getMessage(payload)
  const error = YSweetError.fromMessage(message)
  expect(error.cause).toEqual(payload)
}

test('server refused', () => {
  const payload: YSweetErrorPayload = {
    code: 'ServerRefused',
    address: '127.0.0.1',
    port: 1234,
    url: 'https://foo.bar/baz',
  }

  expectRoundTrip(payload)
})

test('server error', () => {
  const payload: YSweetErrorPayload = {
    code: 'ServerError',
    status: 404,
    message: 'Not found',
    url: 'https://foo.bar/baz',
  }

  expectRoundTrip(payload)
})

test('no auth provided', () => {
  const payload: YSweetErrorPayload = {
    code: 'NoAuthProvided',
  }

  expectRoundTrip(payload)
})

test('invalid auth provided', () => {
  const payload: YSweetErrorPayload = {
    code: 'InvalidAuthProvided',
  }

  expectRoundTrip(payload)
})

test('unknown', () => {
  const payload: YSweetErrorPayload = {
    code: 'Unknown',
    message: 'Something went wrong',
  }

  expectRoundTrip(payload)
})

